function PassengerManifestFields({passenger,onChange,serviceName='',origin='',destination=''}){const defaults={tour_name:serviceName,passenger_origin:origin,passenger_destination:destination};const fields=[['tour_name','Tour'],['passenger_type','Tipo'],['btc','BTC'],['bter','Bter'],['food','Alimentación'],['passenger_origin','Origen'],['passenger_destination','Destino'],['accommodation','Habitación']];return <div className="span-2 passenger-manifest-fields"><div className="form-grid"><label>País<input value={passenger.country||'Perú'} onChange={event=>onChange('country',event.target.value)} placeholder="Perú"/></label><label>Código de venta<output className="generated-sale-code">{passenger.sale_code||'Se genera automáticamente al guardar'}</output></label><label>Usuario (ej. Gloria)<input value={passenger.booked_by||''} onChange={event=>onChange('booked_by',event.target.value)} placeholder="Nombre de quien registró la venta"/></label><label>Agencia<input value={passenger.agency||''} onChange={event=>onChange('agency',event.target.value)} placeholder="Nombre de la agencia"/></label></div><label className="manifest-description-field">Descripción para el manifiesto<textarea rows="2" value={passenger.manifest_description||''} onChange={event=>onChange('manifest_description',event.target.value)} placeholder="Detalle de este pasajero que debe aparecer en el manifiesto"/></label><details className="passenger-manifest-extra"><summary>Más datos del manifiesto</summary><div className="form-grid">{fields.map(([key,label])=><label key={key}>{label}<input value={passenger[key]||defaults[key]||''} onChange={event=>onChange(key,event.target.value)}/></label>)}<label className="span-2">Otra información<textarea rows="2" value={passenger.manifest_notes||''} onChange={event=>onChange('manifest_notes',event.target.value)}/></label></div></details></div>}
function maintenanceReason(reason){return /manten|maten/i.test(String(reason||''));}
function unitMaintenanceActive(unit,date){return !!(unit.maintenance_start||unit.maintenance_end)&&(!unit.maintenance_start||date>=unit.maintenance_start)&&(!unit.maintenance_end||date<=unit.maintenance_end);}
function unitAvailabilityState(unit,services=[],now=new Date()){
 const today=localDate(now);
 if(unit.status==='Mantenimiento')return {status:'En mantenimiento',reason:unit.maintenance_notes||'Marcada manualmente'};
 if(unit.status==='No disponible')return {status:'No disponible',reason:unit.availability_notes||'Marcada manualmente'};
 if(unitMaintenanceActive(unit,today))return {status:'En mantenimiento',reason:unit.maintenance_notes||`Programado hasta ${unit.maintenance_end||'nuevo aviso'}`};
 if(unit.unavailable_start&&unit.unavailable_end){const from=new Date(unit.unavailable_start),to=new Date(unit.unavailable_end),reason=unit.availability_notes||'Bloqueo horario';if(now>=from&&now<to)return {status:maintenanceReason(reason)?'En mantenimiento':'No disponible',reason};if(now<from&&localDate(from)===today)return {status:maintenanceReason(reason)?'Mantenimiento programado':'No disponible programado',reason:`Desde ${from.toLocaleTimeString('es-PE',{hour:'2-digit',minute:'2-digit'})} · ${reason}`};}
 const currentService=services.find(service=>service.date===today&&!['Cancelado','Completado'].includes(service.status)&&(()=>{const start=new Date(`${service.date}T${service.time}`),end=new Date(start.getTime()+Number(service.duration_minutes||120)*60000),assigned=String(service.vehicle||'').toLowerCase(),sameVehicle=assigned.includes(String(unit.plate||'').toLowerCase())||assigned.includes(String(unit.name||'').toLowerCase()),sameDriver=!!unit.delegate&&String(service.driver||'').trim().toLowerCase()===unit.delegate.trim().toLowerCase();return now>=start&&now<end&&(sameVehicle||sameDriver)})());
 if(currentService)return {status:'En servicio',reason:currentService.name};
 if(unit.status==='En servicio')return {status:'En servicio',reason:'Marcada como ocupada'};
 return {status:'Disponible',reason:''};
}
function unitAvailabilityReason(unit,services,date,time,duration,driver){
 if(unit.status==='Mantenimiento')return `En mantenimiento${unit.maintenance_notes?` · ${unit.maintenance_notes}`:''}`;
 if(unit.status==='No disponible')return `No disponible${unit.availability_notes?` · ${unit.availability_notes}`:''}`;
 if(date&&unitMaintenanceActive(unit,date))return `En mantenimiento${unit.maintenance_notes?` · ${unit.maintenance_notes}`:''}`;
 if(date&&time&&unit.unavailable_start&&unit.unavailable_end){const start=new Date(`${date}T${time}`).getTime(),end=start+Number(duration||120)*60000,blockedStart=new Date(unit.unavailable_start).getTime(),blockedEnd=new Date(unit.unavailable_end).getTime();if(start<blockedEnd&&end>blockedStart){const reason=unit.availability_notes||'Bloqueo horario';return `${maintenanceReason(reason)?'En mantenimiento':'No disponible'} · ${reason}`;}}
 if(date&&time){const start=new Date(`${date}T${time}`).getTime(),end=start+Number(duration||120)*60000;const conflict=services.find(service=>service.date===date&&!['Cancelado','Completado'].includes(service.status)&&(()=>{const serviceStart=new Date(`${service.date}T${service.time}`).getTime(),serviceEnd=serviceStart+Number(service.duration_minutes||120)*60000,assignedUnit=String(service.vehicle||'').toLowerCase(),sameUnit=assignedUnit.includes(String(unit.plate||'').toLowerCase())||assignedUnit.includes(String(unit.name||'').toLowerCase()),sameDriver=driver&&String(service.driver||'').trim().toLowerCase()===driver.trim().toLowerCase();return start<serviceEnd&&end>serviceStart&&(sameUnit||sameDriver)})());if(conflict){const reason=conflict.driver?.trim().toLowerCase()===String(driver||'').trim().toLowerCase()?'Conductor asignado': 'Unidad asignada';return `No disponible · ${reason} en ${conflict.name} (${conflict.time})`;}}
 return '';
}
function guideAvailabilityReason(guide,services,date,time,duration){
 if(!guide)return '';
 if(guide.status==='No disponible')return `No disponible${guide.unavailable_reason?` · ${guide.unavailable_reason}`:''}`;
 if(date&&guide.unavailable_start&&guide.unavailable_end&&date>=guide.unavailable_start&&date<=guide.unavailable_end)return `No disponible${guide.unavailable_reason?` · ${guide.unavailable_reason}`:''}`;
 if(date&&time){const start=new Date(`${date}T${time}`).getTime(),end=start+Number(duration||120)*60000;const service=(services||[]).find(item=>item.tour_guide===guide.id&&item.date===date&&!['Cancelado','Completado'].includes(item.status)&&(()=>{const busyStart=new Date(`${item.date}T${item.time}`).getTime(),busyEnd=busyStart+Number(item.duration_minutes||120)*60000;return start<busyEnd&&end>busyStart})());if(service)return `En viaje · ${service.name} (${String(service.time||'').slice(0,5)})`}
 return '';
}

let leafletPromise;
function loadLeaflet(){
 if(window.L)return Promise.resolve(window.L);
 if(leafletPromise)return leafletPromise;
 leafletPromise=new Promise((resolve,reject)=>{
  if(!document.getElementById('leaflet-css')){const link=document.createElement('link');link.id='leaflet-css';link.rel='stylesheet';link.href='https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';document.head.appendChild(link)}
  const script=document.createElement('script');script.src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';script.async=true;script.onload=()=>window.L?resolve(window.L):reject(new Error('No se pudo iniciar el mapa'));script.onerror=()=>reject(new Error('No se pudo cargar el mapa'));document.head.appendChild(script);
 }).catch(error=>{leafletPromise=null;throw error});
 return leafletPromise;
}
function routePoints(route={}){
 const points=[{key:'origin',label:'Origen',latitude:route.origin_latitude,longitude:route.origin_longitude}];
 (route.stops||[]).forEach((stop,index)=>points.push({key:`stop-${index}`,label:`Parada ${index+1}: ${stop.name||'Sin nombre'}`,latitude:stop.latitude,longitude:stop.longitude}));
 points.push({key:'destination',label:'Destino',latitude:route.destination_latitude,longitude:route.destination_longitude});
 return points.filter(point=>point.latitude!==''&&point.longitude!==''&&point.latitude!=null&&point.longitude!=null&&Number.isFinite(Number(point.latitude))&&Number.isFinite(Number(point.longitude))&&Math.abs(Number(point.latitude))<=90&&Math.abs(Number(point.longitude))<=180);
}
function RouteMap({route,editable=false,activePoint='origin',onPick}){
 const host=useRef(null),map=useRef(null),layer=useRef(null),picker=useRef(onPick),active=useRef(activePoint),[state,setState]=useState('loading'),[tilesFailed,setTilesFailed]=useState(false);
 picker.current=onPick;active.current=activePoint;
 const fingerprint=JSON.stringify({origin_latitude:route.origin_latitude,origin_longitude:route.origin_longitude,destination_latitude:route.destination_latitude,destination_longitude:route.destination_longitude,stops:route.stops||[]});
 useEffect(()=>{let alive=true;let instance;loadLeaflet().then(L=>{if(!alive||!host.current)return;instance=L.map(host.current,{scrollWheelZoom:false}).setView([-15.64,-71.60],10);map.current=instance;layer.current=L.layerGroup().addTo(instance);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap contributors'}).on('tileerror',()=>alive&&setTilesFailed(true)).addTo(instance);instance.on('click',event=>{if(picker.current)picker.current(active.current,event.latlng.lat,event.latlng.lng)});setState('ready');setTimeout(()=>instance.invalidateSize(),80)}).catch(()=>alive&&setState('error'));return()=>{alive=false;if(instance){instance.off();instance.remove()}map.current=null;layer.current=null}},[]);
 useEffect(()=>{if(state!=='ready'||!map.current||!layer.current)return;const L=window.L,points=routePoints(route);layer.current.clearLayers();const latlngs=[];points.forEach((point,index)=>{const latlng=[Number(point.latitude),Number(point.longitude)];latlngs.push(latlng);L.circleMarker(latlng,{radius:8,color:'#fff',weight:2,fillColor:point.key===activePoint?'#c4f74b':index===0?'#1d684f':'#ca7544',fillOpacity:1}).addTo(layer.current).bindTooltip(`${index+1}. ${point.label}`)});if(latlngs.length>1)L.polyline(latlngs,{color:'#1d684f',weight:4,opacity:.82,dashArray:'7 8'}).addTo(layer.current);if(latlngs.length>1)map.current.fitBounds(L.latLngBounds(latlngs),{padding:[30,30],maxZoom:13});else if(latlngs.length===1)map.current.setView(latlngs[0],13);else map.current.setView([-15.64,-71.60],10);setTimeout(()=>map.current?.invalidateSize(),80)},[state,fingerprint,activePoint]);
 return <div className={`service-route-map ${editable?'service-route-map-editable':''}`}><div className="service-route-map-host" ref={host} aria-label="Mapa de ruta y paradas"/>{state==='loading'&&<div className="service-route-map-message">Cargando mapa…</div>}{state==='error'&&<div className="service-route-map-message">No se pudo cargar el mapa; puedes continuar con la ruta escrita.</div>}{tilesFailed&&state==='ready'&&<div className="service-route-map-warning">El mapa base no responde. Puedes seguir consultando la ruta escrita.</div>}<p>{editable?'Haz clic en el mapa para ubicar el punto seleccionado.':'Vista referencial del itinerario.'} Los puntos y la ruta permanecen visibles en texto si falla el mapa. © OpenStreetMap contributors.</p></div>
}

