function Reports({data}){const revenue=data.services.reduce((n,s)=>n+serviceTotal(s),0),cost=data.expenses.reduce((n,e)=>n+Number(e.amount||0),0),net=revenue-cost,byType=['Tour privado','Tour público','Expreso','Taxi huésped','Traslado de personal','Logística'].map(t=>({name:t,count:data.services.filter(s=>s.type===t).length})),serviceResults=data.services.map(service=>{const expenses=data.expenses.filter(e=>e.service_id===service.id||(!e.service_id&&e.service===service.name)).reduce((sum,e)=>sum+Number(e.amount||0),0);return {...service,expenses,margin:serviceTotal(service)-expenses,revenue:serviceTotal(service)}});return <><div className="page-heading"><div><div className="eyebrow">INDICADORES DEL NEGOCIO</div><h1>Reportes</h1><p>Resumen de cantidades, ingresos y costos registrados en el sistema.</p></div><button className="button-secondary" onClick={()=>window.print()}><Download size={16}/> Imprimir / Guardar PDF</button></div><div className="metric-grid"><Metric label="Ingresos proyectados" value={fmt(revenue)} hint="Suma de servicios cargados" icon={DollarSign} tone="green"/><Metric label="Gastos registrados" value={fmt(cost)} hint="Suma de egresos" icon={Wallet} tone="amber"/><Metric label="Margen estimado" value={fmt(net)} hint="Ingresos menos gastos" icon={ArrowUpRight} tone="blue"/><Metric label="Pasajeros registrados" value={data.services.reduce((n,s)=>n+Number(s.people||0),0)} hint="En todos los servicios" icon={Users} tone="purple"/></div><div className="reports-grid"><section className="panel report-panel"><div className="panel-head"><div><h2>Servicios por tipo</h2><p>Volumen de operaciones</p></div></div>{byType.map(x=><div className="bar-row" key={x.name}><span>{x.name}</span><div className="bar-track"><i style={{width:`${Math.max(3,x.count/Math.max(1,data.services.length)*100)}%`}}/></div><b>{x.count}</b></div>)}</section><section className="panel report-panel"><div className="panel-head"><div><h2>Estructura de gastos</h2><p>Distribución por categoría</p></div></div>{['Combustible','Conductor','Operación','Proveedor','Otros'].map(cat=>{const n=data.expenses.filter(e=>e.category===cat).reduce((a,e)=>a+Number(e.amount),0);return <div className="cost-row" key={cat}><span><i className="cost-dot"/> {cat}</span><b>{fmt(n)}</b></div>})}<div className="report-note"><CircleHelp size={15}/> Las cifras reflejan únicamente datos ingresados. El margen individual solo incluye gastos vinculados a cada servicio.</div></section></div><section className="panel service-profit-panel"><div className="panel-head"><div><h2>Resultado por servicio</h2><p>Precio registrado menos gastos asociados a cada operación.</p></div><button className="button-primary" onClick={()=>downloadExcel(['Servicio','Tipo','Fecha','Cliente','Ingresos','Gastos','Margen estimado'],serviceResults.map(s=>[s.name,s.type,s.date,s.client,s.revenue,s.expenses,s.margin]),'rentabilidad-servicios-yuyari.xls','Rentabilidad por servicio · AEO Yuyari')}><Download size={16}/> Excel con formato</button><button className="button-secondary" onClick={()=>downloadCsv(['Servicio','Tipo','Fecha','Cliente','Ingresos','Gastos','Margen estimado'],serviceResults.map(s=>[s.name,s.type,s.date,s.client,s.revenue,s.expenses,s.margin]),'rentabilidad-servicios-yuyari.csv')}>CSV simple</button></div><div className="table-wrap"><table><thead><tr><th>SERVICIO</th><th>FECHA</th><th>CLIENTE</th><th>INGRESO</th><th>GASTOS</th><th>MARGEN ESTIMADO</th></tr></thead><tbody>{serviceResults.map(s=><tr key={s.id}><td><b>{s.name}</b><small>{s.type}</small></td><td>{s.date}</td><td>{s.client||'—'}</td><td>{fmt(s.revenue)}</td><td>{fmt(s.expenses)}</td><td><b>{fmt(s.margin)}</b></td></tr>)}</tbody></table>{!serviceResults.length&&<div className="empty-agenda">Aún no hay servicios para calcular.</div>}</div></section></>}
